CREATE TABLE public.app_config (id int PRIMARY KEY DEFAULT 1, data jsonb NOT NULL, CHECK (id=1));
GRANT ALL ON public.app_config TO service_role;
ALTER TABLE public.app_config ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.licenses (id text PRIMARY KEY, license_key text NOT NULL UNIQUE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', amount text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending', duration_label text NOT NULL DEFAULT '1 Month', expires_at timestamptz, lifetime boolean NOT NULL DEFAULT false, max_devices int NOT NULL DEFAULT 1, license_devices jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.licenses TO service_role;
ALTER TABLE public.licenses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.signals (id text PRIMARY KEY, pair text NOT NULL, market text, timer text, mode text, direction text NOT NULL, entry text, expiry text, accuracy text, strength text, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.signals TO service_role;
ALTER TABLE public.signals ENABLE ROW LEVEL SECURITY;
